import '../models/device_history.dart';

List<DeviceHistory> generateTestData() {
  final now = DateTime.now();

  String fmt(DateTime dt) =>
      dt.year.toString().padLeft(4, '0') + '-' +
      dt.month.toString().padLeft(2, '0') + '-' +
      dt.day.toString().padLeft(2, '0') + 'T' +
      dt.hour.toString().padLeft(2, '0') + ':' +
      dt.minute.toString().padLeft(2, '0') + ':' +
      dt.second.toString().padLeft(2, '0');

  final p1Start = now.subtract(const Duration(minutes: 60));
  final p1End = now.subtract(const Duration(minutes: 55));
  final p2Start = now.subtract(const Duration(minutes: 45));
  final p2End = now.subtract(const Duration(minutes: 40));

  return [
    DeviceHistory(
      id: -1001,
      deviceId: 1,
      timestamp: fmt(p1End),
      startTime: fmt(p1Start),
      endTime: fmt(p1End),
      data: _packet1,
      intensityType: 'uint8',
    ),
    DeviceHistory(
      id: -1002,
      deviceId: 1,
      timestamp: fmt(p2End),
      startTime: fmt(p2Start),
      endTime: fmt(p2End),
      data: _packet2,
      intensityType: 'uint8',
    ),
  ];
}

